// Cache an immutable copy at module load — TOOL_SPECS is frozen and never mutates,
// so the previous per-call deep-clone wasted CPU. Callers get the same frozen object.
const FROZEN_TOOL_SPECS = Object.freeze(JSON.parse(JSON.stringify(TOOL_SPECS)));

// Self-critique Phase B tool subset: quickCheck + notebook tools only.
// wolfram_eval / wolfram_eval_batch are intentionally excluded so the Fairy
// cannot create new notebook cells during the self-review pass.
const SELF_CRITIQUE_TOOL_NAMES = new Set([
    'wolfram_quickCheck',
    'wolfbook_getNotebookContext',
    'wolfbook_editCell',
]);
const FROZEN_SELF_CRITIQUE_SPECS = Object.freeze(
    JSON.parse(JSON.stringify(TOOL_SPECS.filter(t => SELF_CRITIQUE_TOOL_NAMES.has(t.function.name))))
);

function getOpenAIToolSpecs()       { return FROZEN_TOOL_SPECS; }
function getSelfCritiqueToolSpecs() { return FROZEN_SELF_CRITIQUE_SPECS; }
function listToolNames()            { return TOOL_SPECS.map(t => t.function.name); }

/**
 * Dispatch a tool call. Never throws on tool failure — always returns a
 * structured result so the Fairy can read the error and self-correct.
 *
 * @param {{ name: string, args: any, signal?: AbortSignal }} call
 * @returns {Promise<{
 *   name: string,
 *   ok: boolean,
 *   kind: string,
 *   summary: string,           // short human-readable line for telemetry + UI
 *   modelPayload: string,      // JSON string fed back to the model as the tool message
 *   durationMs: number,
 *   error: string|null,
 *   raw: object,               // full shim result for the inspector
 * }>}
 */
async function dispatchTool(call) {
    const name = String(call && call.name || '');
    const args = (call && call.args) || {};
    if (!listToolNames().includes(name)) {
        return mkErr(name, 0, 'unknown_tool', `Unknown tool '${name}'. Available: ${listToolNames().join(', ')}.`);
    }

    if (name === 'wolfram_quickCheck') {
        return dispatchQuickCheck(args, call.signal);
    }

    if (name === 'wolfbook_getNotebookContext') {
        return dispatchNotebookContext(args, call.signal);
    }

    if (name === 'wolfbook_editCell') {
        return dispatchEditCell(args, call.signal);
    }

    if (name === 'wolfram_eval') {
        const t0 = Date.now();
        const expr = String(args.expression || '');

        // Hard ban: ClearAll / Clear with Global`* pattern must NEVER be used —
        // agent must call ClearGlobals[] instead (registered Wolfram helper).
        if (/\bClearAll\s*\[|\bClear\s*\[/.test(expr) && /Global/.test(expr)) {
            return mkErr(name, Date.now() - t0, 'banned_expression',
                '⛔ BANNED: ClearAll["Global`*"] and Clear["Global`*"] are forbidden. ' +
                'Use ClearGlobals[] instead — it safely clears non-protected Global` symbols without corrupting the session. ' +
                'Rewrite the cell using ClearGlobals[] and re-run.');
        }

        const r  = await evalOnce({
            expression:     expr,
            timeoutSeconds: args.timeoutSeconds,
            signal:         call.signal,
        });
        const durationMs = Date.now() - t0;

        const summary = (r.ok
            ? `wolfram_eval ok in ${durationMs}ms` + (r.truncated ? ` (truncated ${r.originalLength}→${r.value.length})` : '')
            : `wolfram_eval ${r.kind}: ${r.error || 'unknown error'}`)
            + (r.kernelRestarted ? ' [kernel was restarted mid-call]' : '');

        // Bounded JSON payload returned to the model.
        // IMPORTANT: r.value is already capped at ~4000 chars by wolframShim,
        // but that is still too large when accumulated over 20 tool turns —
        // the growing message history consumes the context window and can cause
        // the model's final Scroll JSON to be truncated mid-string.
        // We therefore cap the per-turn value at MODEL_PAYLOAD_VALUE_CAP chars.
        // The full raw output is still available in `raw` for the UI inspector
        // and the telemetry notebook writer.
        const MODEL_PAYLOAD_VALUE_CAP = 1500;
        const modelValue = typeof r.value === 'string' && r.value.length > MODEL_PAYLOAD_VALUE_CAP
            ? r.value.slice(0, MODEL_PAYLOAD_VALUE_CAP) +
              `\n[...${r.value.length - MODEL_PAYLOAD_VALUE_CAP} more chars truncated — full output in notebook]`
            : r.value;

        // ANY kernel warning (Symbol::tag format) means the computation is
        // suspect — set ok:false so the Fairy is forced to fix and re-run.
        // General::stop implies ≥3 prior messages of the same type (≥10 total).
        const warnMatches = r.messages ? (r.messages.match(/\w+::\w+/g) || []) : [];
        const warnCount   = warnMatches.length;
        const hasStopMsg  = r.messages ? /General::stop/i.test(r.messages) : false;
        const isWarningFailure = r.ok && (warnCount >= 1 || hasStopMsg);

        const modelPayload = JSON.stringify({
            // When there are warnings the output is unreliable — report
            // ok:false so the Fairy treats this as a failed cell and fixes it.
            // value is suppressed entirely on warning failures so the model
            // cannot silently cite an unreliable result.
            ok:           isWarningFailure ? false : r.ok,
            kind:         isWarningFailure ? 'warning_failure' : r.kind,
            value:        isWarningFailure
                              ? '(output suppressed — cell had kernel warnings; fix and re-run before using this result)'
                              : modelValue,
            truncated:    r.truncated || undefined,
            messages:     r.messages || undefined,
            warningCount: warnCount > 0 ? warnCount : undefined,
            prints:       r.prints   || undefined,
            durationMs,
            error:        r.error    || undefined,
            kernelRestarted: r.kernelRestarted || undefined,
            // Prominent error/warning notices — the Fairy must not proceed while these are present.
            errorNotice: (!r.ok || isWarningFailure)
                ? (isWarningFailure
                    ? `⛔ CELL FAILED — kernel emitted ${warnCount} warning(s)${hasStopMsg ? ' including General::stop (further messages suppressed)' : ''}: ${warnMatches.join(', ')}. EVEN A SINGLE WARNING means the output is unreliable (e.g. Part::partd indicates wrong indexing; Set::wrsym indicates a read-only symbol). You MUST fix the code so the cell runs with zero messages, then re-run. Do NOT cite this result.`
                    : '⚠️ TOOL CALL FAILED — fix this before continuing. Do not proceed or submit a Scroll until resolved.')
                : undefined,
            warningNotice: (r.ok && !isWarningFailure && r.messages)
                ? '⚠️ KERNEL WARNINGS present in "messages" field — check carefully. Unevaluated output or pattern-name bugs may require code correction.'
                : undefined,
        });

        return {
            name, ok: r.ok, kind: r.kind, summary, modelPayload, durationMs,
            error: r.ok ? null : (r.error || r.kind), raw: r,
            kernelRestarted: !!r.kernelRestarted,
        };
    }

    if (name === 'wolfram_eval_batch') {
        return dispatchBatchEval(args, call.signal);
    }

    return mkErr(name, 0, 'not_implemented', `Tool '${name}' is registered but not implemented.`);
}

// ── Batch eval dispatch ────────────────────────────────────────────────────

async function dispatchBatchEval(args, signal) {
    const t0 = Date.now();
    const exprs = Array.isArray(args && args.expressions) ? args.expressions : [];
    if (exprs.length < 2 || exprs.length > 8) {
        return mkErr('wolfram_eval_batch', Date.now() - t0, 'bad_args',
            `wolfram_eval_batch requires 2-8 expressions; got ${exprs.length}.`);
    }
    const stopOnError = args.stopOnError !== false; // default true
    const timeoutSeconds = args.timeoutSeconds;
    const results = [];
    let anyKernelRestart = false;
    for (let i = 0; i < exprs.length; i++) {
        if (signal && signal.aborted) {
            results.push({ index: i, ok: false, kind: 'aborted', error: 'batch aborted', value: '' });
            break;
        }
        const expr = String(exprs[i] || '');
        if (/\bClearAll\s*\[|\bClear\s*\[/.test(expr) && /Global/.test(expr)) {
            results.push({
                index: i, ok: false, kind: 'banned_expression',
                error: 'ClearAll/Clear["Global`*"] is banned — use ClearGlobals[]',
                expression: expr.slice(0, 200),
            });
            if (stopOnError) break;
            continue;
        }
        const r = await evalOnce({ expression: expr, timeoutSeconds, signal });
        if (r && r.kernelRestarted) anyKernelRestart = true;
        // Apply same warning-as-failure rule as single wolfram_eval.
        const warnMatches = r.messages ? (r.messages.match(/\w+::\w+/g) || []) : [];
        const isWarningFailure = r.ok && warnMatches.length >= 1;
        const ok = isWarningFailure ? false : r.ok;
        const VALUE_CAP = 800; // tighter cap per-expression in batch
        const value = typeof r.value === 'string' && r.value.length > VALUE_CAP
            ? r.value.slice(0, VALUE_CAP) + `\n[...${r.value.length - VALUE_CAP} more chars truncated]`
            : r.value;
        results.push({
            index: i, ok,
            kind: isWarningFailure ? 'warning_failure' : r.kind,
            expression: expr.slice(0, 200),
            value: isWarningFailure ? '(suppressed — warnings present)' : value,
            messages: r.messages || undefined,
            warningCount: warnMatches.length || undefined,
            durationMs: r.durationMs,
            error: r.error || undefined,
        });
        if (!ok && stopOnError) break;
    }
    const durationMs = Date.now() - t0;
    const allOk = results.length === exprs.length && results.every(x => x.ok);
    const summary = allOk
        ? `wolfram_eval_batch ok (${results.length} exprs) in ${durationMs}ms`
        : `wolfram_eval_batch ${results.filter(x => x.ok).length}/${results.length} succeeded in ${durationMs}ms`;
    const modelPayload = JSON.stringify({
        ok: allOk,
        kind: allOk ? 'batch_ok' : 'batch_partial',
        count: results.length,
        results,
        durationMs,
        kernelRestarted: anyKernelRestart || undefined,
        errorNotice: allOk ? undefined :
            '⚠️ BATCH HAD FAILURES — fix the failing expression(s) before citing any value from this batch. ' +
            'Use wolfbook_editCell on the inserted cells or re-run individual expressions via wolfram_eval.',
    });
    return {
        name: 'wolfram_eval_batch', ok: allOk,
        kind: allOk ? 'batch_ok' : 'batch_partial',
        summary, modelPayload, durationMs,
        error: allOk ? null : 'one or more expressions failed',
        raw: { results, allOk },
        kernelRestarted: anyKernelRestart,
    };
}

// ── Notebook tool dispatch ─────────────────────────────────────────────────

async function dispatchNotebookContext(args, signal) {
    if (!_notebookToolProvider) {
        return mkErr('wolfbook_getNotebookContext', 0, 'not_available',
            'Notebook context tool is not available (provider not wired). ' +
            'Use wolfram_eval to inspect variables instead.');
    }
    const t0 = Date.now();
    try {
        const text = await _notebookToolProvider.getNotebookContext({
            action: args.action || 'brief',
            maxCells: args.maxCells,
        }, signal);
        const durationMs = Date.now() - t0;
        const capped = typeof text === 'string' && text.length > 4000
            ? text.slice(0, 4000) + `\n[...${text.length - 4000} more chars truncated]`
            : text;
        // If the transcript contains KaTeX error markers, prepend a prominent banner
        // so the Fairy sees the action required even before scanning individual cells.
        const hasLatexErrors = typeof capped === 'string' && capped.includes('⛔ LATEX ERRORS');
        const banner = hasLatexErrors
            ? '⛔ ACTION REQUIRED — LaTeX errors found in markdown cells.\n' +
              'Use wolfbook_editCell to fix every flagged cell (see ⛔ LATEX ERRORS markers below).\n' +
              'Do NOT call wolfram_eval or submit until all errors are gone.\n\n'
            : '';
        return {
            name: 'wolfbook_getNotebookContext', ok: true, kind: 'ok', durationMs,
            summary: `wolfbook_getNotebookContext ok in ${durationMs}ms`,
            modelPayload: JSON.stringify({ ok: true, content: banner + capped }),
            error: null, raw: null,
        };
    } catch (e) {
        return mkErr('wolfbook_getNotebookContext', Date.now() - t0, 'error',
            String(e && e.message || e));
    }
}

async function dispatchEditCell(args, signal) {
    if (!_notebookToolProvider) {
        return mkErr('wolfbook_editCell', 0, 'not_available',
            'Notebook edit tool is not available (provider not wired). ' +
            'Use wolfram_eval with a new expression instead.');
    }
    const t0 = Date.now();
    try {
        const text = await _notebookToolProvider.editCell({
            cellId:     args.cellId,
            cellNumber: args.cellNumber,
            newContent: args.newContent,
            run:        args.run,
        }, signal);
        const durationMs = Date.now() - t0;
        return {
            name: 'wolfbook_editCell', ok: true, kind: 'ok', durationMs,
            summary: `wolfbook_editCell ok in ${durationMs}ms`,
            modelPayload: JSON.stringify({ ok: true, result: text }),
            error: null, raw: null,
        };
    } catch (e) {
        return mkErr('wolfbook_editCell', Date.now() - t0, 'error',
            String(e && e.message || e));
    }
}

// ── Quick validation check (no notebook cell, free turn) ──────────────────

async function dispatchQuickCheck(args, signal) {
    const t0   = Date.now();
    const expr = String(args && args.expression || '').trim();
    if (!expr) return mkErr('wolfram_quickCheck', 0, 'bad_args', 'expression must be a non-empty string');

    const r = await evalOnce({
        expression:     expr,
        timeoutSeconds: args.timeoutSeconds || 20,
        signal,
    });
    const durationMs = Date.now() - t0;
    const valStr   = String(r.value || '').trim();
    const isTrue   = valStr === 'True';
    const numVal   = parseFloat(valStr);
    const isNearZero = !isNaN(numVal) && Math.abs(numVal) < 1e-8;
    const passed   = r.ok && (isTrue || isNearZero);
    const isFalse  = r.ok && (valStr === 'False' || (!isNaN(numVal) && Math.abs(numVal) >= 1e-8 && Number.isFinite(numVal)));

    const statusNote = !r.ok
        ? `⛔ Check ERRORED: ${expr.slice(0, 80)} → ${r.error || 'evaluation failed'}. Fix the code and re-check.`
        : passed
            ? `✓ Check PASSED: ${expr.slice(0, 80)} → ${valStr.slice(0, 60)}`
            : isFalse
                ? `✗ Check FAILED: ${expr.slice(0, 80)} → ${valStr.slice(0, 60)}. Fix the relevant cell with wolfbook_editCell, then re-run this check.`
                : `? Check INCONCLUSIVE: ${expr.slice(0, 80)} → ${valStr.slice(0, 60)} (not True/False/≈0 — check expression logic)`;

    const modelPayload = JSON.stringify({
        ok: r.ok,
        passed,
        value: valStr.slice(0, 300),
        error: r.error || undefined,
        durationMs,
        statusNote,
    });

    return {
        name: 'wolfram_quickCheck',
        ok: r.ok,
        kind: r.ok ? (passed ? 'passed' : 'failed') : r.kind,
        summary: `wolfram_quickCheck ${passed ? 'passed' : r.ok ? 'failed' : r.kind} in ${durationMs}ms`,
        modelPayload,
        durationMs,
        error: r.ok ? null : (r.error || r.kind),
        raw: r,
    };
}

function mkErr(name, durationMs, kind, error) {
    return {
        name, ok: false, kind, error, durationMs,
        summary: `${name} ${kind}: ${error}`,
        modelPayload: JSON.stringify({ ok: false, kind, error }),
        raw: null,
    };
}

module.exports = { getOpenAIToolSpecs, getSelfCritiqueToolSpecs, listToolNames, dispatchTool, kernelStatus, setNotebookToolProvider, SELF_CRITIQUE_TOOL_NAMES };
